import { startCareer, completeRace } from '../../lib/career/model'
import { lockRaceEntryWithLog, racesForTurn } from '../../lib/career/race-entry'

/** Deterministic isolated saves generated by the actual shared v4 engine and completion logic. */
export function trustFixture(kind: 'growth' | 'decline' | 'zero') {
  const before = { growth: 30, decline: 72, zero: 100 }[kind]
  const seed = kind === 'decline' ? 8 : 0
  const career = {
    ...startCareer('DEV_HORSE_RED_COMET'),
    event: null,
    eventLog: [],
    eventMisses: 0,
    month: 3,
    careerTurnIndex: 3,
    calendarDate: { year: 2028, month: 6 },
    jockeyTrust: { SEO_JIAN: { starts: 2, trust: before } },
  }
  for (const key of ['speed', 'stamina', 'power', 'guts', 'intelligence'] as const) {
    career.values[key] = 40
  }
  let sequence = 0
  const locked = lockRaceEntryWithLog(
    career,
    { raceId: racesForTurn(3)[0].id, jockeyId: 'SEO_JIAN', tactic: '선행' },
    () => `trust-${kind}-${seed}-${++sequence}`,
  )
  const result = locked.log!.result
  const completed = completeRace(
    locked.career,
    locked.career.raceRun!.raceRunId,
    result.placing,
    result.prizeMoney,
  )
  return { ...locked, log: locked.log!, completed, change: completed.raceRecords[0].trustChange! }
}
